// Custom Worker entry: OpenNext's fetch handler plus a Cron Trigger that refreshes feeds.
// @ts-ignore - generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,

  async scheduled(_event: unknown, env: unknown, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const request = new Request("https://googlereader.internal/api/feeds/refresh-all", {
      method: "POST",
    });
    ctx.waitUntil(handler.fetch(request, env, ctx));
  },
};

// @ts-ignore - generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
